import heapq

from rules import departures, visit_mask


def solve(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = visit_mask(source, required)
    start_state = (source, initial_mask, data["coupons"])
    distance = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue

        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": arrival}

        for edge in graph[node]:
            next_mask = mask | visit_mask(edge["v"], required)
            for next_time, next_remaining in departures(edge, arrival, remaining):
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_time < distance.get(next_state, float("inf")):
                    distance[next_state] = next_time
                    heapq.heappush(
                        queue,
                        (next_time, edge["v"], next_mask, next_remaining),
                    )

    return {"arrival": None}

POLICY = {"coupon_rule": "exact", "minimum_duration": 2}


def departures(edge, arrival, coupons_left):
    depart = max(arrival, edge["open"])
    if depart >= edge["close"]:
        return []

    duration = edge["duration"]
    choices = [(depart + duration, coupons_left)]
    if coupons_left > 0:
        discounted_duration = max(
            POLICY["minimum_duration"], duration - edge.get("discount", 0)
        )
        choices.append((depart + discounted_duration, coupons_left - 1))
    return choices


def visit_mask(node, required):
    mask = 0
    for index, name in enumerate(required):
        if node == name:
            mask |= 1 << index
    return mask
